PLATO_ROUTE = "/por-donde-empezar-a-leer-a-platon/"
FIRST_BOOK_ROUTE = "/que-libro-de-filosofia-leer-primero/"
DESCARTES_ROUTE = "/por-donde-empezar-a-leer-a-descartes/"
